'use strict';
const app=document.querySelector('#app'),modal=document.querySelector('#modal'),content=document.querySelector('#modal-content');
const state={data:null,user:null,csrf:'',storeId:Number(localStorage.getItem('uteb-store')||1),type:localStorage.getItem('uteb-type')||'PICKUP',cart:[],category:'ALL',search:'',sort:'default',page:1,adminTab:'dashboard',adminRows:[],builder:null,group:null,checkoutKey:null,socket:null,routeVersion:0};
const money=n=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(Number(n||0));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>v?new Date(v).toLocaleString('vi-VN'):'—';
const statuses={NEW:'Mới đặt',CONFIRMED:'Đã xác nhận',PREPARING:'Đang chế biến',READY:'Sẵn sàng',DELIVERING:'Đang giao',COMPLETED:'Hoàn tất',CANCELLED:'Đã hủy',PAID:'Đã thanh toán',UNPAID:'Chưa thu tiền',PENDING:'Chờ thanh toán',FAILED:'Thất bại',REFUNDED:'Đã hoàn tiền',REVIEW_REQUIRED:'Cần đối soát',EXPIRED:'Hết hạn thanh toán'};
const badge=(s)=>`<span class="badge-label status-${esc(s)}">${esc(statuses[s]||s)}</span>`;
const store=()=>state.data?.stores.find(x=>x.id===state.storeId)||state.data?.stores[0];
const product=id=>state.data.products.find(x=>x.id===Number(id));
const has=(...roles)=>state.user&&roles.some(r=>state.user.roles.split(',').includes(r));
const empty=(title,text,link='#menu',label='Khám phá thực đơn')=>`<div class="empty"><h2>${esc(title)}</h2><p>${esc(text)}</p><a class="btn btn-primary" href="${link}">${esc(label)}</a></div>`;
function toast(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),4500);}
async function api(path,method='GET',body){const opts={method,credentials:'same-origin',headers:{'X-XSRF-TOKEN':state.csrf}};if(body instanceof FormData)opts.body=body;else if(body!==undefined){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(body);}const res=await fetch('/shop-api'+path,opts);const data=await res.text();let json;try{json=data?JSON.parse(data):null;}catch{throw Error('Máy chủ trả về dữ liệu không hợp lệ.');}if(!res.ok)throw Error(json?.message||`Không thể hoàn tất (${res.status}).`);return json;}
function field(name,label,value='',type='text',required=true){return `<div class="field"><label for="f-${esc(name)}">${esc(label)}</label><input id="f-${esc(name)}" name="${esc(name)}" class="form-control" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='password'?'minlength="8" autocomplete="new-password"':''}></div>`;}
function select(name,label,items,value='',required=true){return `<div class="field"><label for="f-${name}">${esc(label)}</label><select id="f-${name}" name="${name}" class="form-select" ${required?'required':''}>${items.map(x=>{const v=Array.isArray(x)?x[0]:x,t=Array.isArray(x)?x[1]:x;return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`;}).join('')}</select></div>`;}
function textArea(name,label,value='',min=0){return `<div class="field"><label for="f-${name}">${esc(label)}</label><textarea id="f-${name}" name="${name}" class="form-control" rows="3" ${min?`required minlength="${min}"`:''}>${esc(value)}</textarea></div>`;}
function formData(form){const b=Object.fromEntries(new FormData(form));form.querySelectorAll('input[type="checkbox"][name]').forEach(i=>{if(!i.name.startsWith('ing-'))b[i.name]=i.checked;});return b;}
function page(title,subtitle,body){return `<div class="page"><div class="page-title"><div class="eyebrow">UTEB BURRITO KITCHEN</div><h1>${esc(title)}</h1>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${body}</div>`;}
function showModal(html){content.innerHTML=html;if(!modal.open)modal.showModal();setTimeout(()=>content.querySelector('input,select,button,a')?.focus(),30);}
function closeModal(){modal.close();state.builder=null;}
function guestCart(){try{return JSON.parse(localStorage.getItem('uteb-guest-cart')||'[]');}catch{return [];}}
async function refreshCart(){
 state.cartError='';
 if(state.user){try{state.cart=await api('/cart');}catch(e){state.cartError=e.message;}}
 else state.cart=guestCart().map(line=>{
  const p=product(line.productId),ids=(line.ingredientIds||'').split(',').filter(Boolean).map(Number),issues=[];
  if(!p)issues.push('Món không còn bán tại chi nhánh. Vui lòng xóa khỏi giỏ.');
  if(ids.some(id=>!state.data.ingredients.some(i=>i.id===id)))issues.push('Có thành phần tạm hết. Vui lòng sửa món.');
  if(p&&(!p.available||line.quantity>p.stock||line.quantity<1||line.quantity>50))issues.push('Món đã hết hoặc số lượng vượt tồn kho.');
  const q=p?calculateBuilder(p,ids):null;
  return {line,product:p,available:!issues.length,editable:!!p,issues,unitPrice:issues.length?null:q.price,calories:issues.length?null:q.kcal,customization:q?.names||'',total:issues.length?null:q.price*line.quantity};
 });
 document.querySelector('#bag-count').textContent=state.cartError?'!':state.cart.reduce((a,c)=>a+c.line.quantity,0);
}
function setMobileMenu(open){document.querySelector('#main-navigation').classList.toggle('open',open);const button=document.querySelector('#mobile-menu');button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Đóng menu':'Mở menu');}
const headerSizeObserver=new ResizeObserver(entries=>{document.documentElement.style.setProperty('--site-header-height',Math.ceil(entries[0].target.getBoundingClientRect().height)+'px');});
headerSizeObserver.observe(document.querySelector('.site-header'));
function updateNavigation(route){document.querySelectorAll('nav a').forEach(link=>{if(link.hash==='#'+route)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});document.querySelector('#account-button').classList.toggle('is-current',['login','register','verify','forgot','account','admin'].includes(route));}
function updateHeader(){document.querySelector('#account-label').textContent=state.user?'Tài khoản':'Đăng nhập';document.querySelector('#store-label').textContent=store()?.name||'Chọn cửa hàng';document.querySelector('#method-caption').textContent=state.type==='DELIVERY'?'Giao tận nơi':'Nhận tại cửa hàng';document.querySelectorAll('[data-action="method"]').forEach(b=>b.classList.toggle('active',b.dataset.value===state.type));}
async function reloadData(){state.data=await api('/public/bootstrap');state.csrf=state.data.csrf||'';state.user=state.data.user||null;if(!state.data.stores.some(s=>s.id===state.storeId))state.storeId=state.data.stores[0]?.id;updateHeader();await refreshCart();}
function connectRealtime(){if(state.socket){state.socket.deactivate();state.socket=null;}if(!state.user||!window.StompJs)return;state.socket=new StompJs.Client({brokerURL:`${location.protocol==='https:'?'wss':'ws'}://${location.host}/ws`,reconnectDelay:5000,onConnect:()=>state.socket.subscribe('/user/queue/events',message=>{try{const d=JSON.parse(message.body);toast(d.text);if(location.hash.startsWith('#orders')||location.hash.startsWith('#order/')||location.hash.startsWith('#admin'))render();}catch{}})});state.socket.activate();}
function productCard(p){const pending=p.image==='/assets/menu/photo-pending.png';return `<article class="product-card"><button class="btn-linkish p-0 w-100" data-action="build" data-id="${p.id}" aria-label="Chọn ${esc(p.name)}"><img class="product-photo" src="${esc(p.image)}" alt="${pending?'Ảnh món đang cập nhật':'Ảnh '+esc(p.name)}" loading="lazy"></button><div class="product-body"><div class="d-flex justify-content-between"><span class="product-category">${esc(p.category)}${pending?' · ẢNH ĐANG CẬP NHẬT':''}</span><button class="favorite" data-action="favorite" data-id="${p.id}" aria-label="Yêu thích ${esc(p.name)}">♡</button></div><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><div class="product-bottom"><span class="product-price">${money(p.price)}</span><button class="add-button" data-action="build" data-id="${p.id}">${p.customizable?'Tự chọn món':'Thêm vào giỏ'}</button></div><div class="date-info mt-2">${p.calories} kcal ${p.customizable?'nền ước tính':'ước tính'} · ${p.stock>0?'Còn món':'Tạm hết'}</div></div></article>`;}
function home(){let products=state.data.products.filter(p=>p.storeId===state.storeId&&p.category==='Burrito');if(products.length<4)products=state.data.products.filter(p=>p.storeId===state.storeId&&p.customizable).slice(0,4);return `<section class="hero"><div class="hero-copy"><div class="eyebrow">TƯƠI MỖI NGÀY. CUỘN THEO Ý BẠN.</div><h1>Một chiếc cuộn.<br><span>Đúng vị bạn.</span></h1><p>Gà nướng thơm, salsa tươi và những lựa chọn bạn thích. Một bữa ngon, tự tay phối vị.</p><a href="#menu" class="btn btn-primary">Đặt món ngay</a><div class="date-info mt-3">Tự chọn nhân, cơm, đậu và topping.</div></div><div class="hero-visual"><img src="/assets/food.png" alt="Burrito gà nướng với cơm, đậu đen, salsa và chanh"><div class="hero-label"><strong>Chicken Burrito</strong>Cuộn nóng. Nhân tươi. Trọn vị.</div></div></section><div class="trust-strip"><span>CHẾ BIẾN KHI BẠN ĐẶT</span><span>NGUYÊN LIỆU TƯƠI MỖI NGÀY</span><span>THEO KHẨU VỊ CỦA BẠN</span></div><section class="section"><div class="section-heading"><div><div class="eyebrow">CHỌN MÓN BẠN THÍCH</div><h2>Bữa ngon bắt đầu từ đây.</h2></div><a class="home-menu-link" href="#menu">Xem thực đơn</a></div><div class="product-grid featured-grid">${products.map(productCard).join('')}</div><div class="split-promo"><article class="promo-card"><div class="eyebrow">UTEB REWARDS</div><h3>Mỗi bữa ngon,<br>thêm một phần thưởng.</h3><p>Tích 1 điểm cho mỗi 1.000đ của đơn hoàn tất. Đổi điểm lấy ưu đãi cho bữa tiếp theo.</p><a href="#rewards">Khám phá Rewards</a></article><article class="promo-card"><div class="eyebrow">CÙNG BẠN BÈ & ĐỒNG NGHIỆP</div><h3>Đông người.<br>Đủ mọi khẩu vị.</h3><p>Đặt món cùng nhóm hoặc chọn gói burrito cho buổi tiệc của bạn.</p><a href="#groups">Đặt cùng nhóm</a> <a href="#catering">Đặt tiệc</a></article></div></section>`;}
function rewardsJoinBanner(){return state.user?'':`<aside class="rewards-join" aria-label="Tham gia UTEB Rewards"><div class="rewards-join-copy"><img class="rewards-join-logo" src="/assets/uteb-logo.png" alt="" width="76" height="76" aria-hidden="true"><div><h2>THÊM BỮA NGON. THÊM PHẦN THƯỞNG.</h2><p>Gia nhập UTEB Rewards và tích điểm cho mỗi đơn hàng.</p></div></div><div class="rewards-join-actions"><a href="#register" class="btn btn-primary">Tham gia Rewards</a><a href="#login">Đăng nhập</a></div></aside>`;}
function menu(){let ps=state.data.products.filter(p=>p.storeId===state.storeId&&(state.category==='ALL'||p.category===state.category)&&p.name.toLocaleLowerCase('vi').includes(state.search.toLocaleLowerCase('vi')));if(state.sort==='price-asc')ps.sort((a,b)=>a.price-b.price);else if(state.sort==='price-desc')ps.sort((a,b)=>b.price-a.price);else if(state.sort==='new')ps.sort((a,b)=>b.id-a.id);else if(state.sort==='rating'){const rating=id=>{const rs=state.data.reviews.filter(r=>r.productId===id);return rs.length?rs.reduce((n,r)=>n+r.stars,0)/rs.length:0;};ps.sort((a,b)=>rating(b.id)-rating(a.id));}else if(state.sort==='top'){const sold=id=>state.top?.find(x=>x.product.id===id)?.sold||0;ps.sort((a,b)=>sold(b.id)-sold(a.id));}const pages=Math.ceil(ps.length/20);state.page=Math.max(1,Math.min(state.page,pages||1));return page('Hôm nay bạn muốn ăn gì?',`Thực đơn tại ${store()?.name}. Chọn món rồi phối vị theo cách của bạn.`,`${rewardsJoinBanner()}<div class="filter-row"><input id="menu-search" type="search" class="form-control" placeholder="Tìm burrito, bowl, món ăn kèm…" aria-label="Tìm món" value="${esc(state.search)}"><select class="form-select" id="menu-store" aria-label="Chi nhánh">${state.data.stores.map(s=>`<option value="${s.id}" ${s.id===state.storeId?'selected':''}>${esc(s.name)}</option>`).join('')}</select><select class="form-select" id="menu-sort" aria-label="Sắp xếp">${[['default','Gợi ý cho bạn'],['price-asc','Giá tăng dần'],['price-desc','Giá giảm dần'],['new','Món mới'],['rating','Đánh giá cao'],['top','Bán chạy']].map(([v,l])=>`<option value="${v}" ${state.sort===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="tabs">${['ALL',...state.data.categories.map(c=>c.name)].map(c=>`<button class="pill ${state.category===c?'active':''}" data-action="category" data-value="${esc(c)}">${c==='ALL'?'Tất cả':esc(c)}</button>`).join('')}</div><div class="muted mb-3 small">${ps.length} món phù hợp</div>${ps.length?`<div class="product-grid">${ps.slice((state.page-1)*20,state.page*20).map(productCard).join('')}</div><div class="pagination-buttons">${Array.from({length:pages},(_,i)=>`<button class="${i+1===state.page?'active':''}" data-action="page" data-value="${i+1}">${i+1}</button>`).join('')}</div>`:empty('Chưa có món phù hợp','Thử đổi từ khóa hoặc danh mục.','#stores','Đổi cửa hàng')}`);}
function calculateBuilder(p,ids){let price=Number(p.price),kcal=p.calories,names=[];ids.forEach(id=>{const i=state.data.ingredients.find(x=>x.id===id);if(i){price+=Number(i.price);kcal+=p.category==='Kids'?Math.ceil(i.calories/2):i.calories;names.push(i.name);}});const included=includedMenuProteinName(p);if(p.customizable&&included){const base=state.data.ingredients.find(i=>i.groupName==='PROTEIN'&&i.name===included);if(base)price-=Number(base.price);}return{price,kcal,names:names.join(' · ')};}
function menuRequiredGroups(p){if(p.category==='Tacos'||p.category==='Quesadilla')return['PROTEIN','SAUCE'];if(p.category==='Salad')return['PROTEIN','BEANS','SAUCE'];if(p.category==='Kids')return['PROTEIN','RICE','SAUCE'];return['PROTEIN','RICE','BEANS','SAUCE'];}
function includedMenuProteinName(p){if(p.name.endsWith(' Bò BBQ')||p.name.endsWith(' Bò đặc biệt'))return'Bò BBQ';if(p.name.endsWith(' Heo xé'))return'Heo xé';return'';}
function menuIngredientAllowed(p,i){return !p.name.endsWith(' Chay')||!((i.groupName==='PROTEIN'&&i.name!=='Đậu hũ chay')||i.name==='Thêm thịt');}
function suggestedMenuIngredient(p,g){const name=p.name;let target='';if(g==='PROTEIN'){if(name.endsWith(' Chay'))target='Đậu hũ chay';else if(name.endsWith(' Bò BBQ')||name.endsWith(' Bò đặc biệt'))target='Bò BBQ';else if(name.endsWith(' Heo xé'))target='Heo xé';else target='Gà nướng';}else if(g==='SAUCE'&&name.endsWith(' Gà cay'))target='Sốt cay';return state.data.ingredients.find(i=>i.groupName===g&&i.name===target&&i.available&&menuIngredientAllowed(p,i))||state.data.ingredients.find(i=>i.groupName===g&&i.available&&menuIngredientAllowed(p,i));}
function openBuilder(id,editId=null,target='cart'){const p=product(id);if(!p){toast('Món không còn bán.');return;}let line=editId?state.cart.find(c=>String(c.line.id)===String(editId))?.line:null;let ids=line?line.ingredientIds.split(',').filter(Boolean).map(Number):[];if(p.customizable&&!ids.length)menuRequiredGroups(p).forEach(g=>{let i=suggestedMenuIngredient(p,g);if(i)ids.push(i.id);});state.builder={p,editId,target};const groupNames={PROTEIN:'Chọn nhân',RICE:'Chọn cơm',BEANS:'Chọn đậu',SAUCE:'Chọn sốt',TOPPING:'Thêm topping',EXTRA:'Thêm một chút ngon'};const groups=[...menuRequiredGroups(p),'TOPPING','EXTRA'];const rs=state.data.reviews.filter(r=>r.productId===p.id);showModal(`<form id="builder-form"><div class="customize-head"><img src="${esc(p.image)}" alt="Burrito UTEB"><div><div class="eyebrow">${esc(p.category)}</div><h2>${esc(p.name)}</h2><p class="muted small">${esc(p.description)}</p></div></div>${p.customizable?groups.map(g=>`<section class="ingredient-group"><h3>${groupNames[g]} <span class="muted small">${['TOPPING','EXTRA'].includes(g)?'Tùy chọn':'Chọn 1'}</span></h3><div class="ingredient-options">${state.data.ingredients.filter(i=>i.groupName===g&&menuIngredientAllowed(p,i)).map(i=>`<label class="ingredient-option"><input type="${['TOPPING','EXTRA'].includes(g)?'checkbox':'radio'}" name="ing-${g}" value="${i.id}" ${ids.includes(i.id)?'checked':''} ${['TOPPING','EXTRA'].includes(g)?'':'required'}><span>${esc(i.name)}<small>${i.price>0?'+'+money(i.price)+' · ':''}${i.calories} kcal${i.allergens?' · '+esc(i.allergens):''}</small></span></label>`).join('')}</div></section>`).join(''):''}${field('quantity','Số lượng',line?.quantity||1,'number')}${textArea('note','Ghi chú cho bếp',line?.note||'')}<div class="builder-bottom"><div><span id="builder-price" class="price-large"></span><div id="builder-calories" class="muted small"></div></div><button class="btn btn-primary" type="submit">${target==='nutrition'?'Lưu cấu hình':target==='group'?'Thêm vào nhóm':editId?'Cập nhật món':'Thêm vào giỏ'}</button></div></form>${rs.length?`<div class="mt-4"><h3 class="h5">Đánh giá (${rs.length})</h3>${rs.slice(0,4).map(reviewCard).join('')}</div>`:''}`);document.querySelector('[name="quantity"]').setAttribute('min','1');document.querySelector('[name="quantity"]').setAttribute('max','50');updateBuilder();if(state.user)api('/marks/'+p.id,'POST',{kind:'RECENT'}).catch(()=>{});}
function builderIds(){return [...content.querySelectorAll('input[name^="ing-"]:checked')].map(i=>Number(i.value));}
function updateBuilder(){if(!state.builder)return;const q=calculateBuilder(state.builder.p,builderIds()),qty=Number(content.querySelector('[name="quantity"]')?.value||1);document.querySelector('#builder-price').textContent=money(q.price*qty);document.querySelector('#builder-calories').textContent=`${q.kcal} kcal ước tính / phần · ${qty} phần`;}
function storesPage(){return page('Một UTEB ở gần bạn.','Chọn chi nhánh trước khi đặt món để xem đúng thực đơn và phương thức phục vụ.',`<input id="store-search" type="search" class="form-control mb-4" placeholder="Tìm theo tên cửa hàng, địa chỉ…" aria-label="Tìm cửa hàng"><button class="btn btn-outline-primary mb-4" data-action="geolocation">Dùng vị trí hiện tại</button><div class="two-col" id="store-list">${storeCards(state.data.stores)}</div>`);}
function storeCards(stores){return stores.map(s=>`<article class="panel store-card"><span class="badge-label">${s.id===state.storeId?'Đang chọn':'UTEB KITCHEN'}</span><h2 class="mt-3">${esc(s.name)}</h2><div class="store-meta">${esc(s.address)}<br>${esc(s.hours)} · ${esc(s.phone)}</div><p class="small">${s.pickup?'Nhận tại cửa hàng ✓ ':''} ${s.delivery?'Giao tận nơi ✓':''}</p><div class="inline-actions"><button class="btn btn-primary" data-action="select-store" data-id="${s.id}">Đặt tại đây</button><a class="btn btn-outline-primary" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(s.address)}" target="_blank" rel="noopener noreferrer">Chỉ đường</a></div></article>`).join('');}
function openStore(){showModal(`<h2 class="h3 mb-4">Chọn cửa hàng</h2><div class="d-grid gap-3">${storeCards(state.data.stores)}</div>`);}
function cartPage(){
 if(state.cartError)return page('Giỏ hàng của bạn.','',`<section class="panel" role="alert"><p class="error-message">Chưa tải được giỏ hàng: ${esc(state.cartError)}</p><button class="btn btn-primary" data-action="retry">Thử lại</button></section>`);
 if(!state.cart.length)return page('Giỏ hàng của bạn.','',empty('Giỏ hàng đang chờ món ngon','Thêm burrito hoặc món ăn kèm để bắt đầu.'));
 const invalid=state.cart.some(c=>c.available===false),subtotal=state.cart.reduce((n,c)=>n+(c.available===false?0:Number(c.total)),0),groups=Object.groupBy(state.cart,c=>c.line.storeId);
 return page('Giỏ hàng của bạn.',state.user?'Bạn có thể sửa lại từng món trước khi đặt.':'Giỏ được lưu trên thiết bị. Đăng nhập để đặt đơn và đồng bộ giỏ.',`
 <div class="two-col"><div>${Object.entries(groups).map(([sid,lines])=>`<section class="panel mb-4"><h2 class="h5 fw-bold">${esc(state.data.stores.find(s=>s.id===Number(sid))?.name||'Chi nhánh không còn phục vụ')}</h2>${lines.map(c=>`
 <article class="cart-item ${c.available===false?'cart-item-unavailable':''}"><img src="${esc(c.product?.image||'/assets/food.png')}" alt="${esc(c.product?.name||'Món không còn bán')}"><div>
 <h3>${esc(c.product?.name||'Món không còn bán')}</h3><p class="muted small mb-1">${esc(c.customization||'Món cố định')}</p>
 ${c.calories==null?'':`<span class="small muted">${c.calories} kcal / phần</span>`}
 ${c.available===false?`<p class="cart-issue" role="alert">${(c.issues||[]).map(esc).join(' ')}</p>`:''}
 <div class="d-flex gap-3 align-items-center flex-wrap"><div class="quantity"><button data-action="quantity" data-id="${c.line.id}" data-value="-1" aria-label="Giảm số lượng" ${c.available===false?'disabled':''}>−</button><span>${c.line.quantity}</span><button data-action="quantity" data-id="${c.line.id}" data-value="1" aria-label="Tăng số lượng" ${c.available===false?'disabled':''}>+</button></div>
 ${c.editable!==false?`<button class="small-link" data-action="edit-cart" data-id="${c.line.id}">Sửa món</button>`:''}<button class="small-link" data-action="remove-cart" data-id="${c.line.id}">Xóa</button></div></div>
 <div class="fw-bold">${c.total==null?'Cần chọn lại':money(c.total)}</div></article>`).join('')}</section>`).join('')}</div>
 <aside class="panel checkout-summary"><h2 class="h4 fw-bold">Bữa ăn của bạn</h2><div class="summary-row"><span>${state.cart.reduce((n,c)=>n+c.line.quantity,0)} phần</span><strong>${money(subtotal)}</strong></div>
 <div class="summary-row muted small"><span>Phí giao & ưu đãi</span><span>Tính ở bước tiếp theo</span></div><div class="summary-total summary-row"><span>${invalid?'Tạm tính món hợp lệ':'Tạm tính'}</span><span>${money(subtotal)}</span></div>
 ${invalid?'<p class="cart-issue" role="alert">Hãy sửa hoặc xóa các món chưa hợp lệ trước khi đặt.</p><button class="btn btn-primary w-100 mt-3" disabled>Kiểm tra lại giỏ hàng</button>':`<a href="${state.user?'#checkout':'#login'}" class="btn btn-primary w-100 mt-3">${state.user?'Tiến hành đặt món':'Đăng nhập để đặt món'}</a>`}
 <a href="#menu" class="d-block text-center text-wine mt-3 small">Chọn thêm món</a></aside></div>`);
}
async function checkoutPage(){if(!state.user)return loginRequired();await refreshCart();if(state.cartError||state.cart.some(c=>c.available===false))return cartPage();if(!state.cart.length)return page('Đặt món','',empty('Giỏ hàng trống','Hãy chọn món trước khi đặt.'));const account=await api('/account');state.checkoutKey||=crypto.randomUUID();return page('Sắp đến bữa ngon rồi.','Kiểm tra thông tin nhận món và lựa chọn thanh toán.',`<div class="two-col"><form id="checkout-form" class="panel"><h2 class="h5 fw-bold mb-4">Thông tin nhận món</h2>${select('type','Phương thức nhận món',[['PICKUP','Nhận tại cửa hàng'],['DELIVERY','Giao tận nơi']],state.type)}<div class="form-grid">${field('contactName','Họ tên',state.user.name)}${field('phone','Số điện thoại',state.user.phone,'tel')}</div><div id="delivery-fields" ${state.type==='PICKUP'?'hidden':''}>${select('addressId','Địa chỉ đã lưu',[['','Nhập địa chỉ khác'],...account.addresses.map(a=>[a.id,`${a.label}: ${a.detail}`])],'',false)}${textArea('address','Địa chỉ giao hàng')}</div>${select('scheduleMode','Thời gian',[['ASAP','Sớm nhất có thể'],['SCHEDULE','Hẹn giờ']],'ASAP')}${field('scheduledAt','Ngày giờ hẹn','','datetime-local',false)}${textArea('note','Ghi chú đơn hàng')}<h2 class="h5 fw-bold mt-4">Ưu đãi & thanh toán</h2><div class="field"><label for="f-voucher">Mã khuyến mãi</label><div class="input-group"><input id="f-voucher" name="voucher" class="form-control" placeholder="UTEB20"><button class="btn btn-outline-primary" type="button" data-action="preview-checkout">Áp dụng</button></div><span class="muted small">UTEB20: giảm 20%, đơn từ 100.000đ, tối đa 50.000đ.</span></div>${select('paymentMethod','Phương thức thanh toán',[['COD','COD — trả khi nhận món'],...(state.data.vnpayConfigured?[['VNPAY','VNPay Sandbox']]:[]),['MOMO',state.data.demo?'MoMo (Sandbox / giả lập local)':'MoMo Sandbox']],'COD')}<p class="small muted">Giỏ hàng nhiều chi nhánh được tách thành từng đơn và thanh toán riêng. Chỉ sử dụng tài khoản/thẻ thử nghiệm khi thanh toán Sandbox.</p><button type="submit" class="btn btn-primary w-100">Đặt món</button></form><aside class="panel checkout-summary"><h2 class="h4 fw-bold mb-3">Chi tiết thanh toán</h2><div id="checkout-preview">Đang tính tổng…</div></aside></div>`);}
async function updateCheckoutPreview(){const f=document.querySelector('#checkout-form');if(!f)return;const b=formData(f);const el=document.querySelector('#checkout-preview');try{const q=await api('/checkout/preview','POST',b);el.innerHTML=q.parts.map(p=>`<h3 class="h6 fw-bold mt-3">${esc(p.store.name)}</h3><div class="summary-row small"><span>Tiền món</span><span>${money(p.subtotal)}</span></div><div class="summary-row small"><span>Phí giao</span><span>${money(p.deliveryFee)}</span></div><div class="summary-row small text-wine"><span>Giảm giá</span><span>−${money(p.discount)}</span></div>`).join('')+`<div class="summary-total summary-row"><span>Tổng cộng</span><span>${money(q.total)}</span></div><p class="date-info mt-3">Tổng được xác nhận lại khi đặt món.</p>`;}catch(e){el.innerHTML=`<p class="error-message">${esc(e.message)}</p>`;}}
function loginRequired(){return page('Chào mừng bạn đến UTEB.','',empty('Đăng nhập để tiếp tục','Theo dõi đơn, lưu địa chỉ và tích điểm với tài khoản của bạn.','#login','Đăng nhập'));}
function authPage(mode='login'){
 if(mode==='register')return registrationPage();
 if(mode==='login')return loginPage();
 return otpPage(mode);
}
async function accountPage(){if(!state.user)return loginRequired();const d=await api('/account');state.user=d.user;const favorites=d.marks.filter(m=>m.kind==='FAVORITE'),recent=d.marks.filter(m=>m.kind==='RECENT').slice(0,8);return page('Xin chào, '+d.user.name+'.','Thông tin, địa chỉ và những món bạn yêu thích.',`${has('ADMIN','MANAGER','STAFF','VENDOR','SHIPPER')?'<a href="#admin" class="btn btn-primary mb-4">Mở trang quản trị / vận hành</a>':''}<div class="two-col"><section><div class="panel"><h2 class="h4 fw-bold">Hồ sơ</h2><form id="profile-form">${field('name','Họ tên',d.user.name)}${field('phone','Số điện thoại',d.user.phone,'tel',false)}<p class="small muted">${esc(d.user.email)} · ${esc(d.user.roles)}</p><button class="btn btn-primary">Lưu thông tin</button></form><button class="small-link mt-3" data-action="password-modal">Đổi mật khẩu</button> <button class="small-link" data-action="logout">Đăng xuất</button></div><div class="panel mt-4"><div class="section-heading"><h2 class="h4 fw-bold">Địa chỉ</h2><button class="small-link" data-action="address-new">Thêm địa chỉ</button></div>${d.addresses.length?d.addresses.map(a=>`<div class="mb-3"><strong>${esc(a.label)} ${a.defaultAddress?'· Mặc định':''}</strong><p class="small muted mb-1">${esc(a.recipient)} · ${esc(a.phone)}<br>${esc(a.detail)}</p><button class="small-link" data-action="address-edit" data-id="${a.id}">Sửa</button> <button class="small-link" data-action="address-delete" data-id="${a.id}">Xóa</button></div>`).join(''):'<p class="muted">Bạn chưa lưu địa chỉ.</p>'}</div></section><section class="panel"><h2 class="h4 fw-bold">Thông báo</h2>${d.notifications.length?d.notifications.slice(0,20).map(n=>`<div class="notice ${n.seen?'':'unread'}"><p class="mb-1">${esc(n.text)}</p><span class="date-info">${date(n.createdAt)}</span><div>${n.orderId?`<a href="#order/${n.orderId}" class="small-link">Xem đơn</a>`:''} ${!n.seen?`<button class="small-link" data-action="notice-read" data-id="${n.id}">Đánh dấu đã đọc</button>`:''}</div></div>`).join(''):'<p class="muted">Thông báo đơn hàng sẽ xuất hiện ở đây.</p>'}</section></div><h2 class="h4 fw-bold mt-5 mb-3">Món yêu thích</h2>${favorites.length?`<div class="product-grid">${favorites.map(m=>product(m.productId)).filter(Boolean).map(productCard).join('')}</div>`:'<p class="muted">Nhấn biểu tượng ♡ trong thực đơn để lưu món.</p>'}<h2 class="h4 fw-bold mt-5 mb-3">Đã xem gần đây</h2><div class="product-grid">${recent.map(m=>product(m.productId)).filter(Boolean).map(productCard).join('')}</div><div class="panel mt-4"><h2 class="h4 fw-bold">Đăng ký đối tác</h2><p class="muted small">Gửi thông tin cửa hàng để quản trị viên xét duyệt.</p><button class="btn btn-outline-primary" data-action="shop-apply">Đăng ký mở cửa hàng</button>${d.applications.map(a=>`<p class="small mt-2">${esc(a.name)} · ${esc(a.status)} ${esc(a.reply)}</p>`).join('')}</div>`);}
function addressModal(a={}){showModal(`<h2 class="h4 fw-bold">${a.id?'Sửa':'Thêm'} địa chỉ</h2><form id="address-form">${a.id?`<input type="hidden" name="id" value="${a.id}">`:''}${field('label','Tên gợi nhớ',a.label||'Nhà')}${field('recipient','Người nhận',a.recipient||state.user.name)}${field('phone','Điện thoại',a.phone||state.user.phone,'tel')}${textArea('detail','Địa chỉ đầy đủ',a.detail||'',8)}<label class="mb-3"><input type="checkbox" name="defaultAddress" ${a.defaultAddress?'checked':''}> Địa chỉ mặc định</label><button class="btn btn-primary">Lưu địa chỉ</button></form>`);}
function orderCard(o,admin=false){return `<article class="panel order-card"><header><h3>${esc(o.code)}</h3>${badge(o.status)}</header><div class="order-info"><span>${esc(state.data.stores.find(s=>s.id===o.storeId)?.name||'Chi nhánh')} · ${o.type==='DELIVERY'?'Giao tận nơi':'Đến lấy'}</span><span>${date(o.createdAt)}</span></div><div class="d-flex justify-content-between align-items-center gap-2 flex-wrap"><div><strong>${money(o.total)}</strong> <span class="small muted ms-2">${esc(o.paymentMethod)} · ${esc(statuses[o.paymentStatus]||o.paymentStatus)}</span></div><a href="#order/${o.id}" class="btn btn-outline-primary btn-sm">${admin?'Xử lý đơn':'Xem chi tiết'}</a></div></article>`;}
async function ordersPage(){if(!state.user)return loginRequired();const os=(await api('/orders')).filter(o=>o.userId===state.user.id);return page('Đơn hàng của bạn.','Theo dõi món ngon đang được chuẩn bị.',os.length?os.map(o=>orderCard(o)).join(''):empty('Chưa có đơn hàng','Đặt bữa đầu tiên cùng UTEB.'));}
async function orderPage(id){if(!state.user)return loginRequired();const d=await api('/orders/'+id),o=d.order;const flow=o.type==='DELIVERY'?['NEW','CONFIRMED','PREPARING','READY','DELIVERING','COMPLETED']:['NEW','CONFIRMED','PREPARING','READY','COMPLETED'];const index=flow.indexOf(o.status),own=o.userId===state.user.id,operator=has('ADMIN')||(has('STAFF','MANAGER','VENDOR')&&state.user.storeId===o.storeId),shipper=has('SHIPPER')&&o.shipperId===state.user.id;let actions='';if(own&&['NEW','CONFIRMED'].includes(o.status)&&o.paymentStatus!=='PAID')actions+=`<button class="btn btn-outline-primary" data-action="order-status" data-id="${o.id}" data-value="CANCELLED">Hủy đơn</button>`;if((operator||shipper)&&index>=0&&index<flow.length-1){const next=flow[index+1];if(operator||['DELIVERING','COMPLETED'].includes(next))actions+=`<button class="btn btn-primary" data-action="order-status" data-id="${o.id}" data-value="${next}" data-cod="${o.paymentMethod==='COD'&&next==='COMPLETED'}">${next==='COMPLETED'&&o.paymentMethod==='COD'?'Đã thu COD — hoàn tất':esc(statuses[next])}</button>`;}if(own&&o.paymentMethod!=='COD'&&['PENDING','FAILED'].includes(o.paymentStatus)&&o.status!=='CANCELLED')actions+=`<button class="btn btn-primary" data-action="pay" data-id="${o.id}">Thanh toán ${esc(o.paymentMethod)}</button>`;if(own&&o.status==='COMPLETED'&&o.paymentStatus==='PAID'&&!d.refunds.length)actions+=`<button class="btn btn-outline-primary" data-action="refund" data-id="${o.id}">Yêu cầu hoàn tiền</button>`;return page(o.code,`Đặt lúc ${date(o.createdAt)} · ${d.store.name}`,`<div class="two-col"><section><div class="panel"><h2 class="h4 fw-bold">${o.status==='CANCELLED'?'Đơn đã hủy':'Món ngon đang đến'}</h2><p class="small muted">Cập nhật tự động khi cửa hàng thay đổi trạng thái.</p>${o.status==='CANCELLED'?badge(o.status):`<div class="timeline">${flow.map((s,i)=>`<div class="timeline-step ${i<=index?'done':''} ${i===index?'current':''}"><span class="timeline-dot"></span><span>${esc(statuses[s])}</span></div>`).join('')}</div>`}<div class="inline-actions">${actions}</div>${operator&&has('ADMIN','MANAGER','VENDOR')&&o.type==='DELIVERY'&&['NEW','CONFIRMED','PREPARING','READY'].includes(o.status)?`<button class="small-link mt-3" data-action="assign" data-id="${o.id}">Phân công người giao hàng ${o.shipperId?'(đã phân công)':''}</button>`:''}</div><div class="panel mt-4"><h2 class="h4 fw-bold">Món đã đặt</h2>${d.items.map(l=>`<div class="cart-item"><img src="${esc(l.image)}" alt="${esc(l.name)}"><div><h3>${l.quantity} × ${esc(l.name)}</h3><p class="small muted">${esc(l.customization)}</p>${own&&o.status==='COMPLETED'?`<button class="small-link" data-action="review" data-id="${l.id}">Viết đánh giá</button>`:''}</div><strong>${money(l.unitPrice*l.quantity)}</strong></div>`).join('')}</div><div class="panel mt-4"><h2 class="h5 fw-bold">Lịch sử đơn hàng</h2>${d.events.map(e=>`<div class="notice"><strong>${esc(statuses[e.status]||e.status)}</strong><p class="mb-1 small">${esc(e.description)}</p><span class="date-info">${date(e.createdAt)}</span></div>`).join('')}</div></section><aside class="panel checkout-summary"><h2 class="h4 fw-bold">Thông tin nhận món</h2><p><strong>${esc(o.contactName)}</strong><br>${esc(o.phone)}<br>${o.type==='DELIVERY'?esc(o.address):esc(d.store.address)}</p><p class="small muted">${o.type==='DELIVERY'?'Giao tận nơi':'Nhận tại cửa hàng'} · ${o.scheduledAt==='ASAP'?'Sớm nhất có thể':date(o.scheduledAt)}</p>${o.note?`<p class="small">Ghi chú: ${esc(o.note)}</p>`:''}<div class="summary-row"><span>Tiền món</span><span>${money(o.subtotal)}</span></div><div class="summary-row"><span>Giao hàng</span><span>${money(o.deliveryFee)}</span></div><div class="summary-row text-wine"><span>Giảm giá</span><span>−${money(o.discount)}</span></div><div class="summary-total summary-row"><span>Tổng cộng</span><span>${money(o.total)}</span></div><p class="mt-3">${esc(o.paymentMethod)} · ${badge(o.paymentStatus)}</p>${o.transactionRef?`<p class="date-info text-break">Mã giao dịch: ${esc(o.transactionRef)}</p>`:''}${d.refunds.map(r=>`<div class="demo-note">Yêu cầu hoàn: ${esc(r.status)}<br>${esc(r.reply)}${r.evidence?'<br>Bằng chứng: '+esc(r.evidence):''}</div>`).join('')}</aside></div>`);}
function reviewCard(r){return `<article class="review-card"><strong>${esc(r.author)}</strong> <span class="text-wine">${'★'.repeat(r.stars)}${'☆'.repeat(5-r.stars)}</span><p>${esc(r.text)}</p><span class="date-info">${date(r.createdAt)}</span>${r.media?`<div class="review-media">${r.media.split(',').map(u=>u.includes('/video/')?`<video src="${esc(u)}" controls></video>`:`<img src="${esc(u)}" alt="Ảnh đánh giá" loading="lazy">`).join('')}</div>`:''}</article>`;}
async function rewardsPage(){let d=state.user?await api('/account'):null;return page('Bữa ngon. Điểm thưởng.','Tích 1 điểm cho mỗi 1.000đ của đơn đã hoàn tất và thanh toán.',`${d?`<div class="loyalty"><div class="eyebrow">UTEB REWARDS · ${esc(d.user.name)}</div><div class="points">${d.user.points.toLocaleString('vi-VN')} <span class="fs-5">điểm</span></div><p class="mb-0">Điểm được cộng sau khi bạn nhận món.</p></div>`:'<div class="panel mb-4"><h2 class="h4">Gia nhập UTEB Rewards</h2><p class="muted">Lưu những món yêu thích và tích điểm cho mỗi đơn hàng.</p><a href="#register" class="btn btn-primary">Tạo tài khoản</a></div>'}<div class="three-col">${[['DRINK','Thức uống',500,'25.000đ'],['CHIPS','Chips & salsa',800,'35.000đ'],['BURRITO','Một chiếc burrito',1200,'89.000đ']].map(([v,l,p,a])=>`<article class="panel reward-card"><div class="eyebrow">ĐỔI ĐIỂM LẤY ƯU ĐÃI</div><h2 class="h4 fw-bold">${l}</h2><strong>${p} điểm</strong><p class="muted small">Nhận voucher giảm ${a} cho đơn tiếp theo.</p><button class="btn btn-outline-primary" data-action="redeem" data-value="${v}">Đổi thưởng</button></article>`).join('')}</div>${d?`<div class="two-col mt-4"><section class="panel"><h2 class="h4 fw-bold">Voucher đã đổi</h2>${d.rewardVouchers.length?d.rewardVouchers.map(v=>`<div class="notice"><strong>${esc(v.code)}</strong><p class="mb-0 small">${esc(v.name)} · ${v.used?'Đã dùng':'Còn sử dụng'} · hết hạn ${date(v.endsAt)}</p></div>`).join(''):'<p class="muted">Voucher sẽ xuất hiện sau khi đổi thưởng.</p>'}</section><section class="panel"><h2 class="h4 fw-bold">Lịch sử điểm</h2>${d.rewardHistory.map(l=>`<div class="summary-row"><span class="small">${esc(l.description)}</span><strong class="${l.points>0?'text-wine':''}">${l.points>0?'+':''}${l.points}</strong></div>`).join('')}</section></div>`:''}`);}
async function groupPage(code){if(!state.user)return loginRequired();if(!code)return page('Mỗi người một vị. Cùng một đơn.','Tạo nhóm, gửi mã cho bạn bè rồi để mỗi người tự chọn món.',`<div class="two-col"><form class="panel" id="group-create-form"><h2 class="h4 fw-bold">Tạo nhóm mới</h2>${field('title','Tên nhóm','Bữa trưa cùng bạn bè')}${select('storeId','Cửa hàng',state.data.stores.map(s=>[s.id,s.name]),state.storeId)}<button class="btn btn-primary">Tạo nhóm</button></form><form class="panel" id="group-join-form"><h2 class="h4 fw-bold">Tham gia nhóm</h2>${field('code','Mã nhóm')}<button class="btn btn-outline-primary">Mở nhóm</button></form></div>`);const d=await api('/groups/'+encodeURIComponent(code));state.group=d.group;const own=d.group.organizerId===state.user.id;return page(d.group.title,`Mã nhóm: ${d.group.code} · ${state.data.stores.find(s=>s.id===d.group.storeId)?.name}`,`<div class="panel mb-4"><div class="inline-actions"><button class="btn btn-outline-primary" data-action="copy-group" data-value="${esc(d.group.code)}">Sao chép link nhóm</button>${own&&d.group.status==='OPEN'?`<button class="btn btn-primary" data-action="group-checkout" data-value="${esc(d.group.code)}">Khóa nhóm & chuyển vào giỏ</button>`:''}</div><p class="small muted mt-3">${d.group.status==='OPEN'?'Mọi người có thể thêm món. Người tạo nhóm thanh toán toàn bộ sau khi khóa.':'Nhóm đã khóa và chuyển vào giỏ của người tạo.'}</p>${d.lines.map(l=>`<div class="summary-row border-bottom"><span><strong>${esc(l.memberName)}</strong><br><span class="small">${l.quantity} × ${esc(product(l.productId)?.name||'Món đã ngừng bán')}</span></span>${d.group.status==='OPEN'&&(own||l.userId===state.user.id)?`<button class="small-link" data-action="group-remove" data-id="${l.id}">Xóa</button>`:''}</div>`).join('')||'<p class="muted">Chưa có món trong nhóm.</p>'}</div>${d.group.status==='OPEN'?`<h2 class="h4 fw-bold mb-3">Chọn món của bạn</h2><div class="product-grid">${state.data.products.filter(p=>p.storeId===d.group.storeId).map(p=>productCard(p).replaceAll('data-action="build"','data-action="group-build"')).join('')}</div>`:''}`);}
async function cateringPage(){const requests=state.user?await api('/catering'):[];return page('Buổi tiệc ngon hơn với UTEB.','Gói burrito cho buổi họp, sinh nhật hoặc gặp gỡ. Đặt trước ít nhất 24 giờ.',`<div class="three-col mb-4">${[['Burrito Box','Burrito cuộn sẵn, dễ chia phần.','99.000đ / người'],['Build Your Own Party','Cùng phối nhân và topping tại bàn tiệc.','99.000đ / người'],['Chips & Salsa','Món ăn kèm để chia sẻ cùng cả nhóm.','45.000đ / người']].map(([n,t,p])=>`<article class="panel"><div class="eyebrow">UTEB CATERING</div><h2 class="h4 fw-bold">${n}</h2><p class="muted small">${t}</p><strong>${p}</strong></article>`).join('')}</div><div class="two-col"><form class="panel" id="catering-form"><h2 class="h4 fw-bold">Gửi yêu cầu đặt tiệc</h2>${select('packageName','Gói tiệc',['Burrito Box','Build Your Own Party','Chips & Salsa'])}${select('storeId','Cửa hàng',state.data.stores.map(s=>[s.id,s.name]),state.storeId)}<div class="form-grid">${field('people','Số khách (10–500)',20,'number')}${field('eventAt','Ngày giờ tiệc','','datetime-local')}${field('contactName','Người liên hệ',state.user?.name||'')}${field('phone','Điện thoại',state.user?.phone||'','tel')}</div>${textArea('address','Địa chỉ tổ chức')}${textArea('note','Yêu cầu thêm')}<p class="small muted">Cửa hàng sẽ xác nhận yêu cầu và báo giá. Gửi yêu cầu chưa tạo giao dịch thanh toán.</p><button class="btn btn-primary">${state.user?'Gửi yêu cầu':'Đăng nhập để đặt tiệc'}</button></form><section class="panel"><h2 class="h4 fw-bold">Yêu cầu của bạn</h2>${requests.length?requests.map(c=>`<div class="notice"><strong>${esc(c.packageName)}</strong><p class="small mb-1">${c.people} người · ${date(c.eventAt)}<br>Dự kiến ${money(c.quotedTotal)}</p>${badge(c.status)}</div>`).join(''):'<p class="muted">Các yêu cầu đặt tiệc sẽ được lưu tại đây.</p>'}</section></div>`);}
function nutritionPage(){const p=state.data.products.find(p=>p.storeId===state.storeId&&p.customizable);return page('Hiểu bữa ăn của bạn.','Calories được cộng từ phần cơ bản và nguyên liệu bạn chọn. Số liệu trong đồ án là ước tính.',`<div class="two-col"><section class="panel"><h2 class="h4 fw-bold">Tính dinh dưỡng theo khẩu vị</h2><p class="muted">Chọn món và phối nguyên liệu để xem tổng calories cùng thông tin dị ứng.</p>${p?`<button class="btn btn-primary" data-action="nutrition-build" data-id="${p.id}">Tính calories cho burrito</button>`:''}<div id="nutrition-result" class="mt-3"></div></section><section class="panel"><h2 class="h4 fw-bold">Thành phần & dị ứng</h2><div class="table-wrap"><table class="table"><thead><tr><th>Thành phần</th><th>kcal</th><th>Dị ứng</th></tr></thead><tbody>${state.data.ingredients.map(i=>`<tr><td>${esc(i.name)}</td><td>${i.calories}</td><td>${esc(i.allergens||'—')}</td></tr>`).join('')}</tbody></table></div><p class="small muted mt-3">Thông tin mẫu; chưa thay thế dữ liệu kiểm định dinh dưỡng hoặc tư vấn cho người dị ứng.</p></section></div>`);}
function storyPage(){return page('Tươi mỗi ngày. Theo cách của bạn.','UTEB là ý tưởng chuỗi burrito được phát triển trong đồ án nhóm.',`<img class="story-banner" src="/assets/food.png" alt="Burrito tươi với salsa và chanh"><div class="two-col"><div><h2 class="h3 fw-bold">Một chiếc burrito, nhiều lựa chọn.</h2><p class="muted">Bạn chọn món, chọn nhân và thêm những thành phần mình yêu thích. UTEB kết nối việc đặt món với từng chi nhánh để mỗi đơn đến đúng nơi chuẩn bị.</p><a href="#menu" class="btn btn-primary">Khám phá thực đơn</a></div><div class="panel"><h2 class="h4 fw-bold">Từ lựa chọn đến bữa ăn</h2><p>Chọn chi nhánh và cách nhận món.</p><p>Phối nhân, cơm, đậu, sốt và topping.</p><p>Đặt đơn rồi theo dõi quá trình chuẩn bị.</p><a href="#nutrition" class="text-wine">Xem thông tin nguyên liệu</a></div></div>`);}
function helpPage(){return page('UTEB luôn sẵn sàng hỗ trợ.','Tìm câu trả lời trước khi đặt món.',`<div class="two-col"><section class="panel help-box"><h2 class="h4 fw-bold">Câu hỏi thường gặp</h2>${[['Tôi có thể đổi thành phần không?','Có. Chọn món rồi tùy chỉnh nhân, cơm, đậu, sốt và topping. Bạn cũng có thể sửa món trong giỏ trước khi đặt.'],['Phí giao hàng được tính thế nào?','Mỗi chi nhánh có phí riêng. Đơn từ 150.000đ tại một chi nhánh được miễn phí giao của chi nhánh đó.'],['Khi nào tôi có thể hủy đơn?','Bạn có thể hủy đơn chưa thanh toán trực tuyến ở trạng thái mới hoặc đã xác nhận, trước khi bếp chế biến.'],['Tôi tích điểm như thế nào?','Đơn hoàn tất và đã thu tiền được cộng 1 điểm cho mỗi 1.000đ. Điểm đổi thành voucher sử dụng một lần.'],['Làm sao biết đơn đã sẵn sàng?','Trang chi tiết đơn và thông báo tài khoản cập nhật khi nhân viên đổi trạng thái.'],['Thanh toán local có chuyển tiền thật không?','Giả lập local chỉ phục vụ demo. Chỉ cổng Sandbox được cấu hình mới mở trang thanh toán bên ngoài.']].map(([q,a])=>`<details><summary>${q}</summary><p class="muted mt-3">${a}</p></details>`).join('')}</section><section class="panel"><h2 class="h4 fw-bold">Liên hệ chi nhánh</h2>${state.data.stores.map(s=>`<div class="notice"><strong>${esc(s.name)}</strong><p class="small muted">${esc(s.address)}<br><a href="tel:${esc(s.phone.replaceAll(' ',''))}">${esc(s.phone)}</a></p></div>`).join('')}<a href="#orders" class="btn btn-outline-primary mt-3">Xem đơn cần hỗ trợ</a></section></div>`);}
const adminNames={dashboard:'Tổng quan',orders:'Đơn hàng',products:'Thực đơn & tồn kho',ingredients:'Nguyên liệu',categories:'Danh mục',stores:'Chi nhánh',users:'Tài khoản',vouchers:'Khuyến mãi',refunds:'Hoàn tiền',catering:'Đặt tiệc',applications:'Duyệt cửa hàng',media:'Thư viện media',settings:'Cấu hình',audit:'Nhật ký'};
function adminTabs(){if(has('ADMIN'))return Object.keys(adminNames);if(has('MANAGER'))return ['dashboard','orders','products','stores','users','vouchers','refunds','catering','media'];if(has('VENDOR'))return ['dashboard','orders','products','stores','vouchers','refunds','catering','media'];return ['dashboard','orders'];}
async function adminPage(){if(!state.user)return loginRequired();if(!has('ADMIN','MANAGER','STAFF','VENDOR','SHIPPER'))return page('Quản trị','',empty('Bạn không có quyền truy cập','Khu vực này dành cho nhân sự UTEB.'));const tabs=adminTabs();if(!tabs.includes(state.adminTab))state.adminTab='dashboard';let body='';if(state.adminTab==='dashboard'){const d=await api('/admin/dashboard');body=`<h2 class="h3 fw-bold">Tổng quan vận hành</h2><p class="muted small">Doanh thu thực thu từ đơn hoàn tất, đã thanh toán; loại trừ đơn hoàn tiền.</p><div class="stats"><div class="stat"><span>Doanh thu</span><strong>${money(d.revenue)}</strong></div><div class="stat"><span>Đơn hàng</span><strong>${d.orders.length}</strong></div><div class="stat"><span>Khách đã đặt</span><strong>${d.customers}</strong></div><div class="stat"><span>Hoa hồng</span><strong>${money(d.commission)}</strong></div></div><div class="two-col"><section class="panel"><h3 class="h5 fw-bold">Doanh thu theo ngày</h3>${barChart(d.daily,money)}</section><section class="panel"><h3 class="h5 fw-bold">Món bán chạy</h3>${barChart(d.topProducts,n=>n+' phần')}</section></div><div class="section-heading mt-4"><h3 class="h4 fw-bold">Đơn gần đây</h3><button class="small-link" data-action="admin-tab" data-value="orders">Xem tất cả</button></div>${d.orders.slice(0,5).map(o=>orderCard(o,true)).join('')}`;}else if(state.adminTab==='orders'){const os=await api('/orders');state.adminOrders=os;body=`<div class="section-heading"><h2 class="h3 fw-bold">Đơn hàng</h2><button class="btn btn-outline-primary btn-sm" data-action="export-orders">Xuất CSV</button></div><select id="admin-order-filter" class="form-select mb-4" aria-label="Lọc trạng thái"><option value="ALL">Tất cả trạng thái</option>${Object.entries(statuses).filter(([k])=>['NEW','CONFIRMED','PREPARING','READY','DELIVERING','COMPLETED','CANCELLED'].includes(k)).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><div id="admin-orders">${os.map(o=>orderCard(o,true)).join('')||empty('Chưa có đơn','Đơn mới sẽ xuất hiện tại đây.','#admin','Tải lại')}</div>`;}else{state.adminRows=await api('/admin/'+state.adminTab);body=adminTable(state.adminTab,state.adminRows);}return page('Vận hành UTEB.',`${state.user.name} · ${state.user.roles} ${state.user.storeId?'· '+state.data.stores.find(s=>s.id===state.user.storeId)?.name:''}`,`<div class="admin-layout"><aside class="admin-nav">${tabs.map(t=>`<button class="${t===state.adminTab?'active':''}" data-action="admin-tab" data-value="${t}">${adminNames[t]}</button>`).join('')}</aside><section>${body}</section></div>`);}
function barChart(data,format){const entries=Object.entries(data).sort((a,b)=>b[1]-a[1]).slice(0,8),max=Math.max(1,...entries.map(x=>Number(x[1])));return entries.length?entries.map(([k,v])=>`<div class="bar-row"><span>${esc(k)}</span><div class="bar-track"><div class="bar" style="width:${Math.max(2,Number(v)/max*100)}%"></div></div><strong>${esc(format(v))}</strong></div>`).join(''):'<p class="muted small">Chưa có đơn đủ điều kiện ghi nhận.</p>';}
function adminTable(resource,rows){const columns={products:['name','category','price','stock','storeId','available'],ingredients:['name','groupName','price','calories','available'],categories:['name','slug'],stores:['name','address','hours','commission','active'],users:['name','email','roles','storeId','active'],vouchers:['code','name','type','value','minimum','used','endsAt','active'],refunds:['orderId','reason','amount','status'],catering:['packageName','people','eventAt','contactName','quotedTotal','status'],applications:['name','address','phone','status'],media:['url','kind','createdAt'],settings:['name','settingValue'],audit:['actorId','action','detail','createdAt']}[resource]||[];const labels={name:'Tên',category:'Danh mục',price:'Giá',stock:'Tồn kho',storeId:'Chi nhánh',available:'Đang bán',groupName:'Nhóm',calories:'kcal',slug:'Mã',address:'Địa chỉ',hours:'Giờ mở cửa',commission:'Hoa hồng',active:'Hoạt động',email:'Email',roles:'Vai trò',code:'Mã',type:'Loại',value:'Giá trị',minimum:'Tối thiểu',used:'Đã dùng',endsAt:'Hết hạn',orderId:'Đơn',reason:'Lý do',amount:'Số tiền',status:'Trạng thái',packageName:'Gói',people:'Khách',eventAt:'Ngày giờ',contactName:'Liên hệ',quotedTotal:'Báo giá',phone:'Điện thoại',url:'Media',kind:'Loại',createdAt:'Ngày tạo',settingValue:'Giá trị',actorId:'Tài khoản',action:'Thao tác',detail:'Chi tiết'};const canEdit=['products','ingredients','categories','stores','users','vouchers','settings','catering'].includes(resource),canCreate=canEdit&&resource!=='catering'&&(has('ADMIN')||['products','vouchers'].includes(resource)),canDelete=['products','ingredients','categories','stores','users','vouchers','media'].includes(resource);return `<div class="section-heading"><h2 class="h3 fw-bold">${adminNames[resource]}</h2>${canCreate?'<button class="btn btn-primary btn-sm" data-action="admin-new">Thêm mới</button>':''}${resource==='media'?'<button class="btn btn-primary btn-sm" data-action="media-upload">Tải ảnh / video</button>':''}</div><div class="table-wrap"><table class="table"><thead><tr><th>ID</th>${columns.map(c=>`<th>${labels[c]||c}</th>`).join('')}<th>Thao tác</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.id}</td>${columns.map(c=>`<td class="text-limit">${typeof r[c]==='boolean'?(r[c]?'Có':'Không'):['price','minimum','amount','quotedTotal'].includes(c)?money(r[c]):c==='url'?`<a class="small-link" href="${esc(r[c])}" target="_blank" rel="noopener noreferrer">Mở media</a>`:esc(r[c])}</td>`).join('')}<td><div class="inline-actions">${canEdit?`<button class="small-link" data-action="admin-edit" data-id="${r.id}">Sửa</button>`:''}${canDelete?`<button class="small-link" data-action="${resource==='media'?'media-delete':'admin-delete'}" data-id="${r.id}">${resource==='media'?'Xóa media':'Ẩn / xóa'}</button>`:''}${resource==='refunds'?`<button class="small-link" data-action="refund-process" data-id="${r.id}">Xử lý</button>`:''}${resource==='applications'&&r.status==='PENDING'?`<button class="small-link" data-action="shop-approve" data-id="${r.id}">Duyệt</button>`:''}</div></td></tr>`).join('')||`<tr><td colspan="${columns.length+2}" class="text-center muted">Chưa có dữ liệu.</td></tr>`}</tbody></table></div>`;}
function adminEdit(r={}){const t=state.adminTab;let inputs='';const stores=has('ADMIN')?state.data.stores:state.data.stores.filter(s=>s.id===state.user.storeId);const st=()=>select('storeId','Chi nhánh',stores.map(s=>[s.id,s.name]),r.storeId||state.user.storeId||state.storeId);const bool=(name,label,value=true)=>select(name,label,[['true','Có'],['false','Không']],String(r[name]??value));if(t==='products')inputs=field('name','Tên món',r.name)+select('category','Danh mục',state.data.categories.map(c=>c.name),r.category||'Burrito')+st()+field('price','Giá cơ bản',r.price||69000,'number')+field('calories','Calories cơ bản',r.calories||220,'number')+field('stock','Tồn kho',r.stock??100,'number')+productImageField(r.image)+textArea('description','Mô tả',r.description)+bool('available','Đang bán')+bool('customizable','Cho phép tự chọn');else if(t==='ingredients')inputs=field('name','Tên nguyên liệu',r.name)+select('groupName','Nhóm',['PROTEIN','RICE','BEANS','SAUCE','TOPPING','EXTRA'],r.groupName)+field('price','Phụ thu',r.price||0,'number')+field('calories','Calories',r.calories||0,'number')+field('allergens','Thông tin dị ứng',r.allergens,'text',false)+bool('available','Khả dụng');else if(t==='categories')inputs=field('name','Tên danh mục',r.name)+field('slug','Mã danh mục',r.slug);else if(t==='stores')inputs=field('name','Tên cửa hàng',r.name)+field('address','Địa chỉ',r.address)+field('phone','Điện thoại',r.phone)+field('hours','Giờ mở cửa',r.hours||'10:00–22:00')+field('deliveryFee','Phí giao',r.deliveryFee||15000,'number')+(has('ADMIN')?field('commission','Tỷ lệ hoa hồng (0 đến 1)',r.commission??0.1,'number'):'')+bool('pickup','Nhận tại cửa hàng')+bool('delivery','Giao tận nơi')+bool('active','Hoạt động');else if(t==='users')inputs=field('name','Họ tên',r.name)+field('email','Email',r.email,'email')+field('phone','Điện thoại',r.phone,'tel',false)+select('roles','Vai trò',(has('ADMIN')?['CUSTOMER','STAFF','MANAGER','ADMIN','CUSTOMER,VENDOR','SHIPPER']:['STAFF','SHIPPER']),r.roles)+select('storeId','Chi nhánh',[['','Không gán chi nhánh'],...stores.map(s=>[s.id,s.name])],r.storeId||'')+field('password',r.id?'Mật khẩu mới (để trống nếu giữ)':'Mật khẩu', '', 'password',!r.id)+bool('active','Hoạt động');else if(t==='vouchers')inputs=field('code','Mã khuyến mãi',r.code)+field('name','Tên ưu đãi',r.name)+select('storeId','Áp dụng tại',has('ADMIN')?[['','Toàn hệ thống'],...stores.map(s=>[s.id,s.name])]:stores.map(s=>[s.id,s.name]),r.storeId||'')+select('type','Loại giảm',['PERCENT','FIXED'],r.type)+field('value','Giá trị giảm',r.value||20,'number')+field('minimum','Giá trị đơn tối thiểu',r.minimum||0,'number')+field('maxDiscount','Mức giảm tối đa',r.maxDiscount||50000,'number')+field('usageLimit','Giới hạn lượt',r.usageLimit||1000,'number')+field('startsAt','Bắt đầu',(r.startsAt||localDate(-1)).slice(0,16),'datetime-local')+field('endsAt','Kết thúc',(r.endsAt||localDate(30)).slice(0,16),'datetime-local')+bool('active','Hoạt động');else if(t==='catering')inputs=select('status','Trạng thái',['NEW','CONFIRMED','COMPLETED','CANCELLED'],r.status);else if(t==='settings')inputs=field('name','Tên cấu hình',r.name)+field('settingValue','Giá trị',r.settingValue);showModal(`<h2 class="h4 fw-bold mb-4">${r.id?'Chỉnh sửa':'Thêm mới'} · ${adminNames[t]}</h2><form id="admin-form">${r.id?`<input type="hidden" name="id" value="${r.id}">`:''}<div class="form-grid">${inputs}</div><button class="btn btn-primary">Lưu thay đổi</button></form>`);content.querySelectorAll('input[type="number"]').forEach(i=>i.step='any');if(t==='products')bindProductImagePicker(content.querySelector('#admin-form'));}
function localDate(days){const d=new Date(Date.now()+days*86400000);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString();}
async function render(){if(!state.data)return;clearTimeout(state.paymentPoll);state.needsPaymentPoll=false;const seq=++state.routeVersion,hash=location.hash.slice(1)||'home',parts=hash.split('/');try{let html;switch(parts[0]){case'home':html=home();break;case'menu':if(state.sort==='top')state.top=await api('/public/top');html=menu();break;case'stores':html=storesPage();break;case'cart':await refreshCart();html=cartPage();break;case'checkout':html=await checkoutPage();break;case'login':case'register':case'verify':case'forgot':html=authPage(parts[0]);break;case'account':html=await accountPage();break;case'orders':html=await ordersPage();break;case'order':html=await orderPage(parts[1]);break;case'payment-result':html=await vnpayResultPage(parts[1],parts[2]);break;case'rewards':html=await rewardsPage();break;case'groups':html=await groupPage(parts[1]);break;case'catering':html=await cateringPage();break;case'nutrition':html=nutritionPage();break;case'story':html=storyPage();break;case'help':html=helpPage();break;case'admin':html=await adminPage();break;default:html=page('Không tìm thấy trang','',empty('Trang không tồn tại','Bạn có thể quay lại thực đơn.'));}if(seq!==state.routeVersion)return;app.innerHTML=html;schedulePaymentRefresh();updateOtpSendButton();updateNavigation(parts[0]);if(parts[0]==='checkout'&&document.querySelector('#f-scheduledAt')){document.querySelector('#f-scheduledAt').parentElement.hidden=true;await updateCheckoutPreview();}}catch(e){if(seq===state.routeVersion)app.innerHTML=page('Không thể mở trang','',`<div class="panel"><p class="error-message">${esc(e.message)}</p><button class="btn btn-primary" data-action="retry">Thử lại</button> <a href="#login" class="btn btn-outline-primary">Đăng nhập</a></div>`);}}
async function login(email,password){await api('/auth/login','POST',{email,password});await reloadData();const guest=guestCart();for(const line of guest){try{await api('/cart','POST',{...line,id:undefined});const remain=guestCart().filter(x=>x.id!==line.id);localStorage.setItem('uteb-guest-cart',JSON.stringify(remain));}catch(e){toast('Món chưa chuyển được vào giỏ: '+e.message);}}await refreshCart();connectRealtime();const paymentReturn=state.paymentReturnRoute;state.paymentReturnRoute=null;location.hash=paymentReturn|| (has('STAFF','MANAGER','ADMIN','SHIPPER','VENDOR')?'#admin':'#menu');if(location.hash==='#menu'||location.hash==='#admin')await render();toast('Chào mừng '+state.user.name+'!');}
async function actions(button){const action=button.dataset.action,id=button.dataset.id,value=button.dataset.value;switch(action){
 case'close-modal':closeModal();break;case'mobile':setMobileMenu(!document.querySelector('#main-navigation').classList.contains('open'));break;case'account':location.hash=state.user?'#account':'#login';break;case'store':openStore();break;case'select-store':state.storeId=Number(id);localStorage.setItem('uteb-store',id);closeModal();updateHeader();state.page=1;location.hash='#menu';await render();break;
 case'method':state.type=value;localStorage.setItem('uteb-type',value);updateHeader();if(location.hash==='#checkout'){await render();}break;case'build':openBuilder(id);break;case'group-build':openBuilder(id,null,'group');break;case'nutrition-build':openBuilder(id,null,'nutrition');break;
 case'category':state.category=value;state.page=1;await render();break;case'page':state.page=Number(value);await render();window.scrollTo({top:150,behavior:'smooth'});break;case'favorite':if(!state.user){location.hash='#login';break;}await api('/marks/'+id,'POST',{kind:'FAVORITE'});toast('Đã cập nhật món yêu thích.');if(location.hash==='#account')await render();break;
 case'edit-cart':state.data=await api('/public/bootstrap');{const c=state.cart.find(c=>String(c.line.id)===id);openBuilder(c.product.id,id);break;}
 case'quantity':{const c=state.cart.find(c=>String(c.line.id)===id);const quantity=c.line.quantity+Number(value);if(quantity<1||quantity>50)break;requireClient(quantity<=c.product.stock,'Số lượng vượt tồn kho.');if(state.user)await api('/cart','POST',{...c.line,quantity});else{const g=guestCart();g.find(l=>String(l.id)===id).quantity=quantity;localStorage.setItem('uteb-guest-cart',JSON.stringify(g));}await render();break;}
 case'remove-cart':if(state.user)await api('/cart/'+id,'DELETE');else localStorage.setItem('uteb-guest-cart',JSON.stringify(guestCart().filter(l=>String(l.id)!==id)));await render();break;
 case'preview-checkout':await updateCheckoutPreview();break;case'demo-login':await login(value+'@uteb.vn','Uteb@12345');break;case'logout':await api('/auth/logout','POST');state.checkoutKey=null;await reloadData();connectRealtime();location.hash='#home';await render();break;
 case'password-modal':showModal(`<h2 class="h4 fw-bold">Đổi mật khẩu</h2><form id="password-form">${field('currentPassword','Mật khẩu hiện tại','','password')}${field('password','Mật khẩu mới','','password')}<button class="btn btn-primary">Đổi mật khẩu</button></form>`);break;
 case'address-new':addressModal();break;case'address-edit':{const d=await api('/account');addressModal(d.addresses.find(a=>a.id===Number(id)));break;}case'address-delete':if(confirm('Xóa địa chỉ đã lưu này?')){await api('/addresses/'+id,'DELETE');await render();}break;
 case'notice-read':await api('/notifications/'+id+'/read','PUT');await render();break;case'redeem':if(!state.user){location.hash='#login';break;}if(confirm('Đổi điểm lấy voucher này?')){const v=await api('/rewards/redeem','POST',{reward:value});toast('Voucher của bạn: '+v.code);await render();}break;
 case'order-status':{const isCod=button.dataset.cod==='true';if(value==='CANCELLED'&&!confirm('Hủy đơn và trả lại tồn kho?'))break;if(isCod&&!confirm('Bạn xác nhận đã thu đủ số tiền COD của đơn này?'))break;await api('/orders/'+id+'/status','PUT',{status:value,codCollected:isCod});toast('Đã cập nhật trạng thái.');await render();break;}
 case'pay':await launchPayment(id);break;
 case'simulate':await api('/orders/'+id+'/simulate','POST',{success:value==='true'});closeModal();await render();break;
 case'assign':{const shippers=await api('/admin/shippers?orderId='+encodeURIComponent(id));if(!shippers.length){showModal('<h2 class="h4">Chưa có shipper phù hợp</h2><p>Cần tài khoản shipper đang hoạt động, đã xác thực và thuộc cùng chi nhánh với đơn hàng.</p>');break;}showModal(`<h2 class="h4 fw-bold">Phân công người giao hàng</h2><form id="assign-form"><input type="hidden" name="orderId" value="${id}">${select('shipperId','Người giao',shippers.map(s=>[s.id,s.name]))}<button class="btn btn-primary">Phân công</button></form>`);break;}
 case'review':showModal(`<h2 class="h4 fw-bold">Bữa ăn của bạn thế nào?</h2><form id="review-form"><input type="hidden" name="orderLineId" value="${id}">${select('stars','Số sao',[['5','★★★★★ — Rất ngon'],['4','★★★★☆'],['3','★★★☆☆'],['2','★★☆☆☆'],['1','★☆☆☆☆']])}${textArea('text','Chia sẻ trải nghiệm (ít nhất 50 ký tự)','',50)}<div class="field"><label>Ảnh / video (tối đa 3 tệp, 10MB mỗi tệp)</label><input name="reviewFiles" class="form-control" type="file" accept="image/jpeg,image/png,image/webp,video/mp4" multiple></div><button class="btn btn-primary">Gửi đánh giá</button></form>`);break;
 case'refund':showModal(`<h2 class="h4 fw-bold">Yêu cầu hoàn tiền</h2><form id="refund-form"><input type="hidden" name="orderId" value="${id}">${textArea('reason','Lý do (ít nhất 20 ký tự)','',20)}<button class="btn btn-primary">Gửi yêu cầu</button></form>`);break;
 case'copy-group':await navigator.clipboard.writeText(location.origin+'/#groups/'+value);toast('Đã sao chép link nhóm.');break;case'group-remove':await api('/groups/items/'+id,'DELETE');await render();break;case'group-checkout':if(confirm('Khóa nhóm và chuyển tất cả món vào giỏ của bạn?')){await api('/groups/'+value+'/cart','POST',{});await refreshCart();location.hash='#cart';}break;
 case'admin-tab':state.adminTab=value;await render();break;case'admin-new':adminEdit();break;case'admin-edit':adminEdit(state.adminRows.find(r=>r.id===Number(id)));break;case'admin-delete':if(confirm('Ẩn hoặc xóa dữ liệu này? Lịch sử đơn hàng vẫn được giữ.')){await api('/admin/'+state.adminTab+'/'+id,'DELETE');await reloadData();await render();}break;
 case'refund-process':showModal(`<h2 class="h4 fw-bold">Xử lý hoàn tiền</h2><form id="refund-process-form"><input type="hidden" name="id" value="${id}">${select('status','Quyết định',[['APPROVED','Duyệt yêu cầu'],['REJECTED','Từ chối'],['REFUNDED','Đã hoàn tiền (cần bằng chứng)']])}${field('evidence','Mã giao dịch / bằng chứng','','text',false)}${textArea('reply','Phản hồi')}<button class="btn btn-primary">Lưu kết quả</button></form>`);break;
 case'shop-apply':showModal(`<h2 class="h4 fw-bold">Đăng ký mở cửa hàng</h2><form id="shop-apply-form">${field('name','Tên cửa hàng')}${field('address','Địa chỉ')}${field('phone','Điện thoại','','tel')}<button class="btn btn-primary">Gửi đăng ký</button></form>`);break;
 case'shop-approve':showModal(`<h2 class="h4 fw-bold">Xét duyệt cửa hàng</h2><form id="shop-approve-form"><input type="hidden" name="id" value="${id}">${select('approve','Kết quả',[['true','Chấp thuận'],['false','Từ chối']])}${textArea('reply','Phản hồi')}<button class="btn btn-primary">Xác nhận</button></form>`);break;
 case'media-upload':showModal(`<h2 class="h4 fw-bold">Tải media lên Cloudinary</h2><form id="media-form"><input name="file" type="file" class="form-control mb-3" accept="image/jpeg,image/png,image/webp,video/mp4" required><p class="small muted">Ảnh JPEG, PNG, WebP hoặc video MP4. Tối đa 10MB.</p><button class="btn btn-primary">Tải lên</button></form>`);break;
 case'media-delete':if(confirm('Xóa media không còn sử dụng? Ảnh đang gắn với món, đánh giá hoặc lịch sử đơn hàng sẽ bị chặn.')){await api('/media/'+id,'DELETE');await render();toast('Đã xóa media.');}break;
 case'export-orders':{const rows=[['Ma don','Chi nhanh','Trang thai','Thanh toan','Tong tien','Ngay'],...state.adminOrders.map(o=>[o.code,o.storeId,o.status,o.paymentStatus,o.total,o.createdAt])];const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='UTEB-don-hang.csv';a.click();URL.revokeObjectURL(url);break;}
 case'geolocation':requireClient(navigator.geolocation,'Trình duyệt không hỗ trợ vị trí.');navigator.geolocation.getCurrentPosition(pos=>{const distance=s=>Math.hypot(s.latitude-pos.coords.latitude,s.longitude-pos.coords.longitude);document.querySelector('#store-list').innerHTML=storeCards([...state.data.stores].sort((a,b)=>distance(a)-distance(b)));toast('Đã xếp cửa hàng theo vị trí gần nhất (tọa độ mẫu).');},()=>toast('Chưa lấy được vị trí. Bạn có thể tìm bằng địa chỉ.'));break;
 case'retry':await render();break;
}}
function requireClient(ok,message){if(!ok)throw Error(message);}
async function submit(form){const b=formData(form);switch(form.getAttribute('id')){
 case'login-form':await submitLogin(form,b);break;case'register-form':await submitRegistration(form,b);break;
 case'otp-request-form':case'otp-form':await submitOtp(form,b);break;
 case'builder-form':{const p=state.builder.p,ids=builderIds(),q=calculateBuilder(p,ids),quantity=Number(b.quantity),target=state.builder.target;requireClient(quantity>=1&&quantity<=50&&quantity<=p.stock,'Số lượng vượt giới hạn hoặc tồn kho.');if(target==='nutrition'){const html=`<h3 class="h5">${esc(p.name)}</h3><p>${esc(q.names)}</p><strong class="price-large text-wine">${q.kcal} kcal ước tính / phần</strong><p class="small muted">${money(q.price)} / phần</p>`;closeModal();document.querySelector('#nutrition-result').innerHTML=html;break;}const body={productId:p.id,quantity,ingredientIds:ids.join(','),note:b.note};if(target==='group'){await api('/groups/'+state.group.code+'/items','POST',body);closeModal();await render();toast('Đã thêm món vào nhóm.');break;}const editId=state.builder.editId;if(state.user){if(editId)body.id=editId;await api('/cart','POST',body);}else{const lines=guestCart();if(editId){const i=lines.findIndex(l=>String(l.id)===String(editId));lines[i]={...body,id:editId,storeId:p.storeId};}else lines.push({...body,id:crypto.randomUUID(),storeId:p.storeId});localStorage.setItem('uteb-guest-cart',JSON.stringify(lines));}closeModal();await refreshCart();toast(editId?'Đã cập nhật món.':'Đã thêm vào giỏ hàng.');if(location.hash==='#cart')await render();break;}
 case'checkout-form':{b.checkoutKey=state.checkoutKey;b.scheduledAt=b.scheduleMode==='SCHEDULE'?b.scheduledAt:'ASAP';const os=await api('/checkout','POST',b);state.checkoutKey=null;await refreshCart();toast(os.length>1?'Đã tạo '+os.length+' đơn. Mở từng đơn để thanh toán theo chi nhánh.':'Đặt món thành công!');location.hash=os.length>1?'#orders':'#order/'+os[0].id;if(b.paymentMethod==='VNPAY'&&os.length===1)await launchPayment(os[0].id);break;}
 case'profile-form':state.user=await api('/account/profile','PUT',b);updateHeader();toast('Đã lưu hồ sơ.');break;case'password-form':await api('/account/password','PUT',b);closeModal();toast('Đã đổi mật khẩu.');break;
 case'address-form':await api('/addresses','POST',b);closeModal();await render();break;case'assign-form':await api('/orders/'+b.orderId+'/shipper','PUT',b);closeModal();await render();break;
 case'review-form':{const files=form.querySelector('[name="reviewFiles"]').files;requireClient(files.length<=3,'Tối đa 3 ảnh/video.');const urls=[];for(const file of files){const fd=new FormData();fd.append('file',file);urls.push((await api('/media','POST',fd)).url);}b.media=urls.join(',');delete b.reviewFiles;await api('/reviews','POST',b);closeModal();await reloadData();await render();toast('Cảm ơn bạn đã chia sẻ!');break;}
 case'refund-form':await api('/orders/'+b.orderId+'/refund','POST',b);closeModal();await render();toast('Đã gửi yêu cầu hoàn tiền.');break;
 case'group-create-form':{const g=await api('/groups','POST',b);location.hash='#groups/'+g.code;break;}case'group-join-form':location.hash='#groups/'+encodeURIComponent(b.code.toUpperCase());break;
 case'catering-form':if(!state.user){location.hash='#login';break;}await api('/catering','POST',b);toast('Đã gửi yêu cầu đặt tiệc.');await render();break;
 case'admin-form':if(state.adminTab==='products')await prepareProductImage(form,b);await api('/admin/'+state.adminTab,'POST',b);closeModal();await reloadData();await render();toast('Đã lưu thay đổi.');break;
 case'refund-process-form':await api('/refunds/'+b.id,'PUT',b);closeModal();await render();break;case'shop-apply-form':await api('/shops/apply','POST',b);closeModal();await render();toast('Đã gửi đăng ký cửa hàng.');break;
 case'shop-approve-form':await api('/shops/applications/'+b.id,'PUT',b);closeModal();await reloadData();await render();break;case'media-form':{const m=await api('/media','POST',new FormData(form));closeModal();await render();toast('Đã tải lên: '+m.url);break;}
}}
document.addEventListener('click',async e=>{if(e.target.closest('#main-navigation a'))setMobileMenu(false);const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();b.disabled=true;try{await actions(b);}catch(err){toast(err.message);}finally{b.disabled=false;}});
document.addEventListener('submit',async e=>{if(!(e.target instanceof HTMLFormElement))return;e.preventDefault();const button=e.target.querySelector('[type="submit"],button:not([type="button"])'),mediaUpload=e.target.id==='media-form',buttonText=button?.textContent;if(mediaUpload)e.target.querySelector('[data-upload-error]')?.remove();if(button){button.disabled=true;if(mediaUpload)button.textContent='Đang tải lên…';}try{await submit(e.target);}catch(err){if(mediaUpload){const error=document.createElement('p');error.className='error-message';error.dataset.uploadError='';error.setAttribute('role','alert');error.textContent=err.message;button.before(error);}else toast(err.message);}finally{if(button){button.disabled=false;if(mediaUpload)button.textContent=buttonText;}}});
document.addEventListener('change',async e=>{try{if(e.target.closest('#builder-form'))updateBuilder();if(e.target.id==='menu-store'){state.storeId=Number(e.target.value);state.page=1;localStorage.setItem('uteb-store',state.storeId);updateHeader();await render();}if(e.target.id==='menu-sort'){state.sort=e.target.value;state.page=1;await render();}if(e.target.closest('#checkout-form')){if(e.target.name==='type'){state.type=e.target.value;document.querySelector('#delivery-fields').hidden=state.type==='PICKUP';updateHeader();}if(e.target.name==='scheduleMode')document.querySelector('#f-scheduledAt').parentElement.hidden=e.target.value!=='SCHEDULE';await updateCheckoutPreview();}if(e.target.id==='admin-order-filter'){const os=state.adminOrders.filter(o=>e.target.value==='ALL'||o.status===e.target.value);document.querySelector('#admin-orders').innerHTML=os.map(o=>orderCard(o,true)).join('')||'<p class="muted">Không có đơn ở trạng thái này.</p>';}}catch(err){toast(err.message);}});
document.addEventListener('input',e=>{if(e.target.id==='menu-search'){state.search=e.target.value;state.page=1;clearTimeout(state.searchTimer);const start=e.target.selectionStart;state.searchTimer=setTimeout(async()=>{await render();const el=document.querySelector('#menu-search');el?.focus();el?.setSelectionRange(start,start);},200);}if(e.target.id==='store-search'){const term=e.target.value.toLocaleLowerCase('vi');document.querySelector('#store-list').innerHTML=storeCards(state.data.stores.filter(s=>(s.name+' '+s.address).toLocaleLowerCase('vi').includes(term)));}if(e.target.closest('#builder-form'))updateBuilder();});
modal.addEventListener('click',e=>{if(e.target===modal){const rect=modal.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal.open&&document.querySelector('#main-navigation').classList.contains('open')){setMobileMenu(false);document.querySelector('#mobile-menu').focus();}});
window.addEventListener('hashchange',()=>{closeModal();setMobileMenu(false);render();window.scrollTo(0,0);});
(async()=>{try{await reloadData();connectRealtime();await render();}catch(e){app.innerHTML=page('UTEB đang chuẩn bị.','',`<div class="panel"><p class="error-message">${esc(e.message)}</p><p>Kiểm tra ứng dụng đã khởi động rồi tải lại trang.</p></div>`);}})();
